import { chromium } from \"@playwright/test\";
const browser = await chromium.launch({channel:\"chrome\"});
const results=[]; let errors=[];
for (const width of [320,390,768,1440]) {
 const page=await browser.newPage({viewport:{width,height:900}}); page.on(\"console\",m=>{if(m.type()===\"error\") errors.push(m.text())}); page.on(\"pageerror\",e=>errors.push(e.message));
 await page.goto(\"http://127.0.0.1:4174/analytics\");
 const audit=await page.evaluate(()=>{const els=[...document.querySelectorAll(\"button,a,input,select,textarea,[role=button]\")].filter(e=>{const s=getComputedStyle(e); const r=e.getBoundingClientRect(); return s.visibility"'!=="hidden"&&s.display!=="none"&&r.width&&r.height}); const dims=els.map(e=>{const r=e.getBoundingClientRect(); return {name:e.getAttribute("aria-label")||e.textContent?.trim()||e.tagName,w:Math.round(r.width),h:Math.round(r.height)}); return {viewport:document.documentElement.clientWidth,document:document.documentElement.scrollWidth,minW:Math.min(...dims.map(d=>d.w)),minH:Math.min(...dims.map(d=>d.h)),offenders:dims.filter(d=>d.w<44||d.h<44),count:dims.length};}); results.push({width,audit}); await page.close();
}
const page=await browser.newPage({viewport:{width:1440,height:900}}); page.on("console",m=>{if(m.type()==="error") errors.push(m.text())}); page.on("pageerror",e=>errors.push(e.message)); await page.goto("http://127.0.0.1:4174/analytics");
await page.getByRole("button",{name:"7 days"}).click(); const pending=await page.locator(".dashboard-content").getAttribute("aria-busy"); await page.waitForTimeout(500); const refreshed=await page.locator(".metric-value-row strong").first().textContent(); const selected=await page.getByRole("button",{name:"7 days"}).getAttribute("aria-pressed");
const dl=page.waitForEvent("download"); await page.getByRole("button",{name:"Export CSV"}).click(); const download=await dl; const suggested=download.suggestedFilename(); const exported=await page.getByRole("button").filter({hasText:"Exported"}).isVisible();
await page.getByRole("button",{name:"Toggle color theme"}).click(); const dark=await page.evaluate(()=>document.documentElement.classList.contains("dark"));
await page.keyboard.press("Tab"); const firstFocus=await page.evaluate(()=>document.activeElement?.getAttribute("aria-label")||document.activeElement?.textContent?.trim()); await page.keyboard.press("Tab"); const secondFocus=await page.evaluate(()=>document.activeElement?.textContent?.trim());
const flow={pending,refreshed,selected,suggested,exported,dark,firstFocus,secondFocus}; await page.close();
const reduce=await browser.newPage({viewport:{width:390,height:900}, reducedMotion:"reduce"}); await reduce.goto("http://127.0.0.1:4174/analytics"); await reduce.getByRole("button",{name:"90 days"}).click(); const reduced=await reduce.evaluate(()=>({busy:document.querySelector(".dashboard-content")?.getAttribute("aria-busy"),duration:getComputedStyle(document.querySelector(".dashboard-content")).transitionDuration,metric:document.querySelector(".metric-value-row strong")?.textContent})); await reduce.waitForTimeout(450); reduced.settled=await reduce.evaluate(()=>document.querySelector(".dashboard-content")?.getAttribute("aria-busy")); await reduce.close();
console.log(JSON.stringify({results,flow,reduced,errors},null,2)); await browser.close();
'"'"

